                                track_id,
                                play_request_id,
                                loaded_track,
                                start_playback,
                            );
                            if let PlayerState::Loading { .. } = self.state {
                                error!("The state wasn't changed by start_playback()");
                                exit(1);
                            }
                        }
                        Poll::Ready(Err(e)) => {
                            debug!(
                                "Current load failed for <{track_id}> at {position_ms} ms as {:?}",
                                e.kind
                            );
                            current_load_failure = Some((
                                track_id,
                                play_request_id,
                                position_ms,
                                start_playback,
