fn log_tracks(label: &str, tracks: &[Value]) {
    let mut shown = 0;
    for (index, track) in tracks.iter().enumerate() {
        if index < FIRST_TRACKS || diagnostic_track(track) {
            log_track(label, index, track);
            shown += 1;
        }
    }
