    fn handle_player_stop(&mut self) {
        self.crossfade_load_ack = None;
        self.cancel_secondary_source("player stopped");
        if let Some(recovery) = self.recovery.take() {
            debug!(
                "Stop cancelled recovery generation {} for <{}> at {} ms",
                recovery.generation, recovery.track_id, recovery.position_ms
            );
            self.next_recovery_generation();
            self.network_health = RecoveryHealth::Healthy;
            self.ensure_sink_stopped(false);
            self.state = PlayerState::Stopped;
            self.send_event(PlayerEvent::Stopped {
                track_id: recovery.track_id,
                play_request_id: recovery.play_request_id,
            });
            return;
        }

        self.next_recovery_generation();
        match self.state {
            PlayerState::Playing {
                ref track_id,
                play_request_id,
                ..
            }
            | PlayerState::Paused {
                ref track_id,
                play_request_id,
                ..
            }
            | PlayerState::EndOfTrack {
                ref track_id,
                play_request_id,
                ..
            }
            | PlayerState::Loading {
                ref track_id,
                play_request_id,
                ..
            } => {
                let track_id = track_id.clone();

                self.ensure_sink_stopped(false);
                self.send_event(PlayerEvent::Stopped {
                    track_id,
                    play_request_id,
                });
                self.state = PlayerState::Stopped;
            }
            PlayerState::Stopped => (),
            PlayerState::Invalid => {
                error!("PlayerInternal::handle_player_stop in invalid state");
                exit(1);
            }
        }
    }

    fn handle_play(&mut self) {
        if let Some(recovery) = self.recovery.as_mut() {
            debug!(
                "Updating play intent during recovery generation {} for <{}>",
                recovery.generation, recovery.track_id
            );
            recovery.set_play_intent(true);
            return;
        }

        match self.state {
            PlayerState::Paused {
                ref track_id,
                play_request_id,
                ref source,
                ..
            } => {
                let track_id = track_id.clone();
                let position_ms = source.stream_position_ms;

                self.state.paused_to_playing();
                self.send_event(PlayerEvent::Playing {
                    track_id,
                    play_request_id,
                    position_ms,
                });
                self.ensure_sink_running();
            }
            PlayerState::Loading {
                ref mut start_playback,
                ..
            } => {
                *start_playback = true;
            }
            _ => error!("Player::play called from invalid state: {:?}", self.state),
        }
    }

    fn handle_pause(&mut self) {
        if let Some(recovery) = self.recovery.as_mut() {
            debug!(
                "Updating pause intent during recovery generation {} for <{}>",
                recovery.generation, recovery.track_id
            );
            recovery.set_play_intent(false);
            self.ensure_sink_stopped(true);
            return;
        }

        match self.state {
            PlayerState::Paused { .. } => self.ensure_sink_stopped(false),
            PlayerState::Playing {
                ref track_id,
                play_request_id,
                ref source,
                ..
            } => {
                let track_id = track_id.clone();
                let position_ms = source.stream_position_ms;

                self.state.playing_to_paused();

                self.ensure_sink_stopped(false);
                self.send_event(PlayerEvent::Paused {
                    track_id,
                    play_request_id,
                    position_ms,
                });
            }
            PlayerState::Loading {
                ref mut start_playback,
                ..
            } => {
                *start_playback = false;
            }
            _ => error!("Player::pause called from invalid state: {:?}", self.state),
        }
    }

    fn handle_packet(
        &mut self,
        packet: Option<(AudioPacketPosition, AudioPacket)>,
        normalisation_factor: f64,
    ) {
        match packet {
            Some((packet_position, packet)) => {
                if packet.is_empty() {
                    return;
                }

                match packet {
                    AudioPacket::Samples(mut samples) => {
                        let volume = self.volume_getter.attenuation_factor();
                        self.apply_source_normalisation(&mut samples, normalisation_factor, volume);

                        let channels = NUM_CHANNELS as usize;
                        let packet_frames = samples.len() / channels;
                        if let Some(offset_frames) = self.transition_mix_offset_frames(
                            packet_position.position_ms,
                            packet_frames,
                        ) {
                            let offset_samples = offset_frames.saturating_mul(channels);
                            if offset_samples > 0 {
                                let transition_samples = samples.split_off(offset_samples);
                                let prefix = self
                                    .transition
                                    .render(AudioPacket::Samples(samples), None)
                                    .expect("armed current-only prefix rendering must be legal");
        samples: &mut [f64],
        normalisation_factor: f64,
        volume: f64,
    ) {
        if !self.config.normalisation {
            return;
        }

        let apply_factor = match self.config.normalisation_method {
            NormalisationMethod::Dynamic => true,
            NormalisationMethod::Basic => normalisation_factor < 1.0 || volume < 1.0,
        };
        if apply_factor && normalisation_factor != 1.0 {
            for sample in samples {
                *sample *= normalisation_factor;
            }
        }
    }

    fn apply_global_output_dsp(&mut self, samples: &mut [f64], volume: f64) {
        if self.config.normalisation
            && self.config.normalisation_method == NormalisationMethod::Dynamic
        {
            let threshold_db = self.config.normalisation_threshold_dbfs;
            let knee_db = self.config.normalisation_knee_db;
            let attack_cf = self.config.normalisation_attack_cf;
            let release_cf = self.config.normalisation_release_cf;

            for sample in samples {
                // Source gain has already been applied. This single limiter intentionally sees
                // the combined transition output.
                *sample += f64::MIN_POSITIVE;
                let bias_db = ratio_to_db(sample.abs()) - threshold_db;
                let knee_boundary_db = bias_db * 2.0;
                let limiter_db = if knee_boundary_db < -knee_db {
                    0.0
                } else if knee_boundary_db.abs() <= knee_db {
                    let term = knee_boundary_db + knee_db;
                    term * term * self.normalisation_knee_factor
                } else {
                    bias_db
                };

                let channel = self.normalisation_channel;
                self.normalisation_channel ^= 1;
                let integrator = &mut self.normalisation_integrators[channel];
                let peak = &mut self.normalisation_peaks[channel];
                *integrator = f64::max(
                    limiter_db,
                    release_cf * *integrator + (1.0 - release_cf) * limiter_db,
                );
                *peak = attack_cf * *peak + (1.0 - attack_cf) * *integrator;
                let max_peak = f64::max(self.normalisation_peaks[0], self.normalisation_peaks[1]);
                *sample *= db_to_ratio(-max_peak) * volume;
            }
        } else if volume < 1.0 {
            for sample in samples {
                *sample *= volume;
            }
        }
    }

    fn write_output_packet(&mut self, mut packet: AudioPacket, volume: f64) -> bool {
        if let AudioPacket::Samples(samples) = &mut packet {
            self.apply_global_output_dsp(samples, volume);
        }
        self.write_sink_packet(packet)
    }

