    fn cancel_secondary_source(&mut self, reason: &str) {
        self.transition.cancel(reason);
        let preload = mem::replace(&mut self.preload, PlayerPreload::None);
        if !matches!(preload, PlayerPreload::None) {
            self.next_secondary_generation();
        }
        match preload {
            PlayerPreload::None => {}
            PlayerPreload::Loading { track_id, .. } => {
                debug!("Secondary source load for <{track_id}> cancelled: {reason}");
            }
            PlayerPreload::Ready { track_id, .. } => {
                debug!("Secondary playback source for <{track_id}> cancelled: {reason}");
            }
        }
    }

    fn cancel_transition(&mut self, reason: &str) {
        self.transition.cancel(reason);
        if let PlayerPreload::Ready { source, .. } = &mut self.preload {
            if let Some(position_ms) = source.decoder.finish_transition_dsp() {
                source.stream_position_ms = position_ms;
            }
        }
    }

    fn start_secondary_decode(&mut self) -> Result<bool, DecoderError> {
        if self.config.passthrough {
            return Ok(false);
        }

        let should_start = matches!(
            &self.preload,
            PlayerPreload::Ready { source, .. } if !source.decoder.is_worker()
        );
        if !should_start {
            return Ok(false);
        }

        let speed_automation = self
            .preload
            .transition_plan()
            .and_then(TransitionPlan::next_speed_automation)
            .cloned();
        let pcm_channel_capacity = match self.preload.transition() {
            Some(PreloadTransition::NormalCrossfade) => {
                Self::duration_frame_count(self.config.normal_crossfade_duration)
                    .div_ceil(SECONDARY_PCM_CHUNK_FRAMES)
                    .max(SECONDARY_PCM_CHANNEL_CAPACITY)
            }
            Some(PreloadTransition::SafetyFallback | PreloadTransition::Scheduled(_)) | None => {
                SECONDARY_PCM_CHANNEL_CAPACITY
            }
        };

        let generation = self.next_secondary_generation();
        let PlayerPreload::Ready {
            track_id, source, ..
        } = &mut self.preload
        else {
            unreachable!("ready secondary changed while starting decoder worker");
        };

        source.decoder.start_secondary(
            source.stream_loader_controller.clone(),
            generation,
            track_id.to_string(),
            speed_automation,
            source.stream_position_ms,
            pcm_channel_capacity,
        )
    }

