impl Drop for SecondaryDecodeWorker {
    fn drop(&mut self) {
        self.cancel();
    }
}

fn run_decode_worker(
    mut decoder: Decoder,
    sender: SyncSender<SecondaryDecodeMessage>,
    cancelled: Arc<AtomicBool>,
    finished: Arc<AtomicBool>,
    generation: u64,
    track_label: &str,
) {
    debug!("Secondary decode started for <{track_label}>");
    let mut reported_ready = false;
    let mut pending_samples = Vec::with_capacity(SECONDARY_PCM_CHUNK_SAMPLES);
    let mut pending_position = None;

    while !cancelled.load(Ordering::Acquire) {
        match decoder.next_packet() {
            Ok(Some((position, AudioPacket::Samples(samples)))) => {
                let mut offset = 0;
                while offset < samples.len() {
                    if cancelled.load(Ordering::Acquire) {
                        finished.store(true, Ordering::Release);
                        return;
                    }

                    if pending_samples.is_empty() {
                        let frame_offset = offset / NUM_CHANNELS as usize;
                        let position_offset_ms =
                            (frame_offset as u64 * 1000 / u64::from(SAMPLE_RATE)) as u32;
                        pending_position = Some(AudioPacketPosition {
                            position_ms: position.position_ms.saturating_add(position_offset_ms),
                            skipped: position.skipped && offset == 0,
                        });
                    }

                    let take = (SECONDARY_PCM_CHUNK_SAMPLES - pending_samples.len())
                        .min(samples.len() - offset);
                    pending_samples.extend_from_slice(&samples[offset..offset + take]);
                    offset += take;

                    if pending_samples.len() == SECONDARY_PCM_CHUNK_SAMPLES {
                        let message = SecondaryDecodeMessage {
                            generation,
                            event: SecondaryDecodeEvent::Packet(
                                pending_position
                                    .take()
                                    .expect("buffered secondary PCM must retain its position"),
                                AudioPacket::Samples(mem::take(&mut pending_samples)),
                            ),
                        };
                        if sender.send(message).is_err() {
                            finished.store(true, Ordering::Release);
                            return;
                        }
                        pending_samples = Vec::with_capacity(SECONDARY_PCM_CHUNK_SAMPLES);
                        if !reported_ready {
                            debug!("Secondary PCM ready for transition for <{track_label}>");
                            reported_ready = true;
                        }
                    }
                }
            }
            Ok(Some((_, AudioPacket::Raw(_)))) => {
                let error = DecoderError::PassthroughDecoder(
                    "secondary PCM decode received an encoded packet".into(),
                );
                debug!("Secondary decode failed for <{track_label}>: {error}");
                let _ = sender.send(SecondaryDecodeMessage {
                    generation,
                    event: SecondaryDecodeEvent::Failed(error),
                });
                break;
            }
            Ok(None) => {
                debug!("Secondary EOF for <{track_label}>");
                if !pending_samples.is_empty()
                    && sender
                        .send(SecondaryDecodeMessage {
                            generation,
                            event: SecondaryDecodeEvent::Packet(
                                pending_position
                                    .take()
                        },
                    },
                    play.context.pages.pop(),
                    fallback_index,
                )
                .await?;

                self.connect_state.set_origin(play.play_origin)
            }
            Pause(_) => self.handle_pause(),
            SeekTo(seek_to) => {
                // for some reason the position is stored in value, not in position
                trace!("seek to {seek_to:?}");
                self.handle_seek(seek_to.value)
            }
            SetShufflingContext(shuffle) => self.handle_shuffle(shuffle.value)?,
            SetRepeatingContext(repeat_context) => {
                self.handle_repeat_context(repeat_context.value)?
            }
            SetRepeatingTrack(repeat_track) => self.handle_repeat_track(repeat_track.value),
            AddToQueue(add_to_queue) => {
                self.cancel_transition_hydrations();
                self.connect_state.add_to_queue(add_to_queue.track, true);
                self.eagerly_preload_mixer_edge_if_known("queue changed");
            }
            SetQueue(set_queue) => {
                self.cancel_transition_hydrations();
                self.connect_state.handle_set_queue(set_queue);
                self.eagerly_preload_mixer_edge_if_known("queue changed");
            }
            SetOptions(set_options) => {
                if let Some(repeat_context) = set_options.repeating_context {
                    self.handle_repeat_context(repeat_context)?
                }

                if let Some(repeat_track) = set_options.repeating_track {
                    self.handle_repeat_track(repeat_track)
                }

                let shuffle = set_options.shuffling_context;
                if let Some(shuffle) = shuffle {
                    self.handle_shuffle(shuffle)?;
                }
            }
            SkipNext(skip_next) => self.handle_next(skip_next.track.map(|t| t.uri))?,
            SkipPrev(_) => self.handle_prev()?,
            Resume(_) if matches!(self.play_status, SpircPlayStatus::Stopped) => {
                self.load_track(true, 0)?
            }
            Resume(_) => self.handle_play(),
        }

