    { source = "target/release/spotifyd", dest = "/usr/bin/spotifyd", mode = "755" },
    { source = "README.md", dest = "/usr/share/doc/spotifyd/README", mode = "644" },
    { source = "contrib/spotifyd.service", dest = "/etc/systemd/user/spotifyd.service", mode = "644" },
]

[profile.release]
lto = true

##### uncomment to test the newest librespot git version
##### use Monke-Array librespot fork

[patch.crates-io]
librespot-audio = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-playback = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-core = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-discovery = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-connect = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-metadata = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-protocol = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
librespot-oauth = { git = "https://github.com/Monke-Array/librespot", rev = "87f23002a1b3a0460fe6d70fefa38bd6560f7057" }
